<?php
namespace App\Entity;
use Doctrine\DBAL\Types\Types;use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] class CustomerPayment { #[ORM\Id,ORM\GeneratedValue,ORM\Column]private ?int $id=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?Stations $station=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?Customer $customer=null;#[ORM\ManyToOne,ORM\JoinColumn(nullable:false)]private ?User $performedBy=null;#[ORM\Column(type:Types::DATE_IMMUTABLE)]private ?\DateTimeImmutable $paymentDate=null;#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $amount='0';#[ORM\Column(length:30)]private string $paymentMethod='CASH';#[ORM\Column(length:80,nullable:true)]private ?string $reference=null;#[ORM\Column(length:255,nullable:true)]private ?string $note=null;#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $previousBalance='0';#[ORM\Column(type:Types::DECIMAL,precision:15,scale:2)]private string $remainingBalance='0';#[ORM\Column]private ?\DateTimeImmutable $createdAt=null; public function getId():?int{return $this->id;}public function getStation():?Stations{return $this->station;}public function setStation(Stations $v):static{$this->station=$v;return $this;}public function getCustomer():?Customer{return $this->customer;}public function setCustomer(Customer $v):static{$this->customer=$v;return $this;}public function getPerformedBy():?User{return $this->performedBy;}public function setPerformedBy(User $v):static{$this->performedBy=$v;return $this;}public function getPaymentDate():?\DateTimeImmutable{return $this->paymentDate;}public function setPaymentDate(\DateTimeImmutable $v):static{$this->paymentDate=$v;return $this;}public function getAmount():string{return $this->amount;}public function setAmount(string $v):static{$this->amount=$v;return $this;}public function getPaymentMethod():string{return $this->paymentMethod;}public function setPaymentMethod(string $v):static{$this->paymentMethod=$v;return $this;}public function getReference():?string{return $this->reference;}public function setReference(?string $v):static{$this->reference=$v;return $this;}public function getNote():?string{return $this->note;}public function setNote(?string $v):static{$this->note=$v;return $this;}public function getPreviousBalance():string{return $this->previousBalance;}public function setPreviousBalance(string $v):static{$this->previousBalance=$v;return $this;}public function getRemainingBalance():string{return $this->remainingBalance;}public function setRemainingBalance(string $v):static{$this->remainingBalance=$v;return $this;}public function getCreatedAt():?\DateTimeImmutable{return $this->createdAt;}public function setCreatedAt(\DateTimeImmutable $v):static{$this->createdAt=$v;return $this;} }
